 1	// By `lol sort` here, I refer to a seemingly-broken sorting algorithm,
 2	// which actually somehow manages to work perfectly:
 3	//
 4	// for i in 0..n
 5	//   for j in 0..n
 6	//     if i < j
 7	//       swap a[i], a[j]
 8	//
 9	// It is perhaps the simpliest sorting algorithm to "memorize",
10	// even "symmetrically beautiful" as if `i` and `j` just played highly
11	// similar roles. And technically it's still O(n^2) time lol...
12	//
13	// Proving its correctness is tricky (interesting) though.
14	
15	// Successfully verified with [Dafny 3.3.0.31104] in about 5 seconds.
16	
17	
18	
19	// We define "valid permutation" using multiset:
20	predicate valid_permut(a: seq<int>, b: seq<int>)
21	  requires |a| == |b|
22	{
23	  multiset(a) == multiset(b)
24	}
25	
26	// This is a swap-based sorting algorithm, so permutedness is trivial:
27	// note that: if i == j, the spec just says a[..] remains the same.
28	method swap(a: array<int>, i: int, j: int)
29	  requires 0 <= i < a.Length && 0 <= j < a.Length
30	  modifies a
31	  ensures a[..] == old(a[..]) [i := old(a[j])] [j := old(a[i])]
32	  ensures valid_permut(a[..], old(a[..]))
33	{
34	  a[i], a[j] := a[j], a[i];
35	}
36	
37	// We then define "sorted" (by increasing order):
38	predicate sorted(a: seq<int>)
39	{
40	  forall i, j | 0 <= i <= j < |a| :: a[i] <= a[j]
41	}
42	
43	
44	// Now, the lol sort algorithm:
45	// (Some invariants were tricky to find, but Dafny was smart enough otherwise)
46	method lol_sort(a: array<int>)
47	  modifies a
48	  ensures valid_permut(a[..], old(a[..]))
49	  ensures sorted(a[..])
50	{
51	  for i := 0 to a.Length
52	    invariant valid_permut(a[..], old(a[..]))
53	    invariant sorted(a[..i])
54	  {
55	    for j := 0 to a.Length
56	      invariant valid_permut(a[..], old(a[..]))
57	      invariant j < i ==> forall k | 0 <= k < j :: a[k] <= a[i]
58	      invariant j < (i) - 1 ==> sorted(a[..i])
59	      invariant j >= i ==> sorted(a[..i+1])
60	    {
61	      if a[i] < a[j] {
62	        swap(a, i, j);
63	      }
64	    }
65	  }
66	}
67	
68	
69	
70	method Main() {
71	  var a := new int[] [3,1,4,1,5,9,2,6];
72	  lol_sort(a);
73	  print a[..];
74	  // `expect` is a run-time assert, more suitable than `assert` on complicated testcases:
75	  expect a[..] == [1,1,2,3,4,5,6,9]; 
76	
77	  var empty := new int[] [];
78	  lol_sort(empty);
79	  assert empty[..] == [];
80	}

